// Scaled from the same WebP portraits shown by the Midway character picker.
import {characters} from './characters.js';
const atlas = new Image();
atlas.src = 'data:image/webp;base64,';
const columns = new Map(characters.map((c,i)=>[c.id,i]));
export function drawCharacterToken(ctx, player, ringColor){
 const column=columns.get(player.characterId) ?? 0;
 const x=player.x, y=player.y-11;
 ctx.save();
 ctx.beginPath();
 ctx.arc(x,y,19,0,2*Math.PI);
 ctx.fillStyle='#233947';
 ctx.fill();
 ctx.strokeStyle=ringColor;
 ctx.lineWidth=3;
 ctx.stroke();
 ctx.clip();
 if(atlas.complete && atlas.naturalWidth) ctx.drawImage(atlas,column*96,0,96,96,x-19,y-19,38,38);
 ctx.restore();
}
